## Task: Port js/pos-tagger.js to TypeScript with TDD

### Context
Read `scripts/slop-score/prompt.md` for full project context.

### Prerequisites
- Task #1 (project structure) must be complete

### What to do

#### Step 1: Write tests first
Create `scripts/slop-score/src/__tests__/pos-tagger.test.ts`:

```typescript
import { describe, test, expect } from 'bun:test';
import { tagText, getPosTagger } from '../lib/pos-tagger';

describe('POS Tagger', () => {
  test('tags simple sentence', () => {
    const result = tagText('The cat sat on the mat.');
    expect(result).toBeDefined();
    expect(Array.isArray(result)).toBe(true);
  });

  test('identifies nouns', () => {
    const result = tagText('The dog runs fast.');
    const tags = result.map(t => t.tag);
    expect(tags).toContain('NN'); // or whatever tag format wink uses
  });

  test('identifies verbs', () => {
    const result = tagText('She runs quickly.');
    const tags = result.map(t => t.tag);
    expect(tags.some(t => t.startsWith('VB'))).toBe(true);
  });

  test('handles empty string', () => {
    const result = tagText('');
    expect(result).toEqual([]);
  });
});
```

#### Step 2: Implement the module
Create `scripts/slop-score/src/lib/pos-tagger.ts` by porting from `js/pos-tagger.js`:

```typescript
import posTagger from 'wink-pos-tagger';

const tagger = posTagger();

export interface TaggedToken {
  value: string;
  tag: string;
  pos: string;
  // Add other properties from wink-pos-tagger output
}

export function getPosTagger() {
  return tagger;
}

export function tagText(text: string): TaggedToken[] {
  if (!text.trim()) return [];
  return tagger.tagSentence(text);
}

// Port any other functions from js/pos-tagger.js
```

#### Step 3: Verify tests pass
```bash
cd scripts/slop-score && bun test src/__tests__/pos-tagger.test.ts
```

